begin
  foreach unit in array array['1', '3'] loop
    select count(*), min(id::text)::uuid, string_agg(name || ' [' || coalesce(plant_code, '') || ']', ', ') into n, pid, cand
      from console.customers where parent_id is not null
       and (name ~* ('unit[ _-]*' || unit || '($|[^0-9])') or coalesce(plant_code, '') ~* ('(^|[^0-9a-z])(u|unit)?[ _-]*' || unit || '($|[^0-9])'));
    if n <> 1 then raise notice 'Unit-% skipped: % plants matched (%).', unit, n, coalesce(cand, 'none'); continue; end if;
    raise notice 'Unit-%: %', unit, pg_temp.rmp_load(pid, d, true, '2026-11');
  end loop;
end $$;
